const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

// In-memory user store (would be DB in production)
const users = new Map();
const sessions = new Map();

// Circuit breaker state per IP
class CircuitBreaker {
  constructor() {
    this.states = new Map();
    this.THRESHOLD = 5;
    this.TIMEOUT = 30000; // 30 seconds
    this.HALF_OPEN_MAX = 1;
  }

  getState(key) {
    if (!this.states.has(key)) {
      this.states.set(key, {
        failures: 0,
        state: 'CLOSED',
        lastFailure: 0,
        halfOpenAttempts: 0
      });
    }
    return this.states.get(key);
  }

  recordFailure(key) {
    const breaker = this.getState(key);
    breaker.failures += 1;
    breaker.lastFailure = Date.now();
    if (breaker.failures >= this.THRESHOLD) {
      breaker.state = 'OPEN';
    }
  }

  recordSuccess(key) {
    const breaker = this.getState(key);
    breaker.failures = 0;
    breaker.state = 'CLOSED';
    breaker.halfOpenAttempts = 0;
  }

  canAttempt(key) {
    const breaker = this.getState(key);
    if (breaker.state === 'CLOSED') return true;
    if (breaker.state === 'OPEN') {
      const elapsed = Date.now() - breaker.lastFailure;
      if (elapsed >= this.TIMEOUT) {
        breaker.state = 'HALF_OPEN';
        breaker.halfOpenAttempts = 0;
        return true;
      }
      return false;
    }
    if (breaker.state === 'HALF_OPEN') {
      if (breaker.halfOpenAttempts < this.HALF_OPEN_MAX) {
        breaker.halfOpenAttempts += 1;
        return true;
      }
      return false;
    }
    return false;
  }
}

const circuitBreaker = new CircuitBreaker();

// Rate limiting per username to prevent credential stuffing
const usernameAttempts = new Map();

function recordUsernameAttempt(username) {
  const now = Date.now();
  if (!usernameAttempts.has(username)) {
    usernameAttempts.set(username, []);
  }
  const attempts = usernameAttempts.get(username);
  attempts.push(now);
  // Keep only last 60 seconds of attempts
  const cutoff = now - 60000;
  while (attempts.length > 0 && attempts[0] < cutoff) {
    attempts.shift();
  }
}

function isUsernameLocked(username) {
  if (!usernameAttempts.has(username)) return false;
  const attempts = usernameAttempts.get(username);
  const now = Date.now();
  const cutoff = now - 60000;
  const recentAttempts = attempts.filter(t => t >= cutoff);
  return recentAttempts.length >= 10;
}

async function authenticate(username, password, clientIp) {
  // Check circuit breaker for IP
  if (!circuitBreaker.canAttempt(clientIp)) {
    return { success: false, error: 'Too many attempts. Please wait.' };
  }

  // Check username-level lockout
  if (isUsernameLocked(username)) {
    return { success: false, error: 'Account temporarily locked.' };
  }

  const user = users.get(username);
  if (!user) {
    // Record failure for non-existent user
    circuitBreaker.recordFailure(clientIp);
    recordUsernameAttempt(username);
    return { success: false, error: 'Invalid credentials.' };
  }

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) {
    circuitBreaker.recordFailure(clientIp);
    recordUsernameAttempt(username);
    return { success: false, error: 'Invalid credentials.' };
  }

  // Success - reset circuit breaker for this IP
  circuitBreaker.recordSuccess(clientIp);
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { username, createdAt: Date.now() });
  return { success: true, token };
}

// WebSocket chat handler
wss.on('connection', (ws, req) => {
  const clientIp = req.socket.remoteAddress;
  let authenticated = false;
  let currentUser = null;

  ws.on('message', async (data) => {
    try {
      const msg = JSON.parse(data);

      if (msg.type === 'auth') {
        const result = await authenticate(msg.username, msg.password, clientIp);
        if (result.success) {
          authenticated = true;
          currentUser = msg.username;
          ws.send(JSON.stringify({ type: 'auth_success', token: result.token }));
        } else {
          ws.send(JSON.stringify({ type: 'auth_failed', error: result.error }));
        }
      } else if (msg.type === 'chat') {
        if (!authenticated) {
          ws.send(JSON.stringify({ type: 'error', error: 'Not authenticated' }));
          return;
        }
        // Broadcast message
        const chatMsg = JSON.stringify({
          type: 'chat',
          from: currentUser,
          message: msg.message,
          timestamp: Date.now()
        });
        wss.clients.forEach(client => {
          if (client.readyState === WebSocket.OPEN) {
            client.send(chatMsg);
          }
        });
      } else if (msg.type === 'auth_token') {
        // Authenticate via existing token - does NOT reset circuit breaker
        const session = sessions.get(msg.token);
        if (session && (Date.now() - session.createdAt) < 3600000) {
          authenticated = true;
          currentUser = session.username;
          ws.send(JSON.stringify({ type: 'auth_success' }));
        } else {
          ws.send(JSON.stringify({ type: 'auth_failed', error: 'Invalid token' }));
        }
      }
    } catch (e) {
      ws.send(JSON.stringify({ type: 'error', error: 'Invalid message format' }));
    }
  });
});

// Registration endpoint
app.use(express.json());
app.post('/register', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || username.length < 3 || password.length < 8) {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }
  const passwordHash = await bcrypt.hash(password, 12);
  users.set(username, { passwordHash, createdAt: Date.now() });
  res.status(201).json({ message: 'User created' });
});

server.listen(3000, () => console.log('Chat server on port 3000'));

module.exports = { server, authenticate, circuitBreaker };
